import express from 'express';
import pg from 'pg';
import bcrypt from 'bcrypt';
import crypto from 'crypto';

const app = express();
const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://user:pass@localhost/authdb'
});

app.use(express.json());

// Rate limiting: track failed attempts per email (in-memory, use Redis in production)
const failedAttempts = new Map();
const RATE_LIMIT = 5;
const LOCKOUT_MS = 15 * 60 * 1000;

function isLockedOut(email) {
  const attempt = failedAttempts.get(email);
  if (!attempt) return false;
  if (attempt.count >= RATE_LIMIT && Date.now() - attempt.lastAttempt < LOCKOUT_MS) {
    return true;
  }
  if (Date.now() - attempt.lastAttempt > LOCKOUT_MS) {
    failedAttempts.delete(email);
    return false;
  }
  return false;
}

function recordFailure(email) {
  const attempt = failedAttempts.get(email) || { count: 0, lastAttempt: Date.now() };
  attempt.count += 1;
  attempt.lastAttempt = Date.now();
  failedAttempts.set(email, attempt);
}

function resetFailures(email) {
  failedAttempts.delete(email);
}

// POST /signup: register new user
app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password || password.length < 8) {
    return res.status(400).json({ error: 'Email and password (min 8 chars) required' });
  }

  try {
    const existing = await pool.query('SELECT id FROM users WHERE email = $1', [email]);
    if (existing.rows.length > 0) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const hashedPassword = await bcrypt.hash(password, 12);
    const userId = crypto.randomUUID();

    await pool.query(
      'INSERT INTO users (id, email, password_hash) VALUES ($1, $2, $3)',
      [userId, email, hashedPassword]
    );

    res.status(201).json({ userId, email });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Signup failed' });
  }
});

// POST /login: issue session
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (isLockedOut(email)) {
    return res.status(429).json({ error: 'Too many failed attempts, try again later' });
  }

  try {
    const user = await pool.query('SELECT id, password_hash FROM users WHERE email = $1', [email]);

    if (user.rows.length === 0) {
      recordFailure(email);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const match = await bcrypt.compare(password, user.rows[0].password_hash);
    if (!match) {
      recordFailure(email);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    resetFailures(email);

    const sessionToken = crypto.randomBytes(32).toString('hex');
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    await pool.query(
      'INSERT INTO sessions (user_id, token, expires_at) VALUES ($1, $2, $3)',
      [user.rows[0].id, sessionToken, expiresAt]
    );

    res.json({ sessionToken, expiresAt });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Middleware: verify session
async function authenticateSession(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No session token' });

  try {
    const session = await pool.query(
      'SELECT user_id FROM sessions WHERE token = $1 AND expires_at > NOW()',
      [token]
    );
    if (session.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid or expired session' });
    }
    req.userId = session.rows[0].user_id;
    next();
  } catch (err) {
    res.status(500).json({ error: 'Auth check failed' });
  }
}

// GET /profile: protected route
app.get('/profile', authenticateSession, async (req, res) => {
  try {
    const user = await pool.query('SELECT id, email FROM users WHERE id = $1', [req.userId]);
    res.json(user.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Profile fetch failed' });
  }
});

// POST /logout: revoke session
app.post('/logout', authenticateSession, async (req, res) => {
  const token = req.headers.authorization.split(' ')[1];
  try {
    await pool.query('DELETE FROM sessions WHERE token = $1', [token]);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: 'Logout failed' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Auth server on port ${PORT}`));

